CREATE TABLE IF NOT EXISTS analytics.sales_by_state ("CustomerState" VARCHAR(8) NOT NULL, "OrdersCount" INTEGER, "UniqueCustomers" INTEGER, "TotalSales" DECIMAL(38,18), "AvgItemPrice" DECIMAL(38,18), "AvgDeliveryTime" DECIMAL(38,18), "LastUpdated" TIMESTAMP, "SourceBatchID" VARCHAR(256) NOT NULL, PRIMARY KEY ("CustomerState")) DISTSTYLE AUTO SORTKEY ("CustomerState");
CREATE TABLE IF NOT EXISTS analytics.sales_by_category ("ProductCategoryNameEnglish" VARCHAR(256) NOT NULL, "OrdersCount" INTEGER, "UniqueCustomers" INTEGER, "TotalSales" DECIMAL(38,18), "AvgItemPrice" DECIMAL(38,18), "AvgDeliveryTime" DECIMAL(38,18), "DelayedOrders" INTEGER, "LastUpdated" TIMESTAMP, "SourceBatchID" VARCHAR(256) NOT NULL, PRIMARY KEY ("ProductCategoryNameEnglish")) DISTSTYLE AUTO SORTKEY ("ProductCategoryNameEnglish");
CREATE TABLE IF NOT EXISTS analytics.monthly_sales ("Year" INTEGER NOT NULL, "Month" INTEGER NOT NULL, "OrdersCount" INTEGER, "UniqueCustomers" INTEGER, "TotalSales" DECIMAL(38,18), "AvgItemPrice" DECIMAL(38,18), "LastUpdated" TIMESTAMP, "SourceBatchID" VARCHAR(256) NOT NULL, PRIMARY KEY ("Year", "Month")) DISTSTYLE AUTO SORTKEY ("Year", "Month");
CREATE TABLE IF NOT EXISTS analytics.order_status ("ProductCategoryNameEnglish" VARCHAR(256) NOT NULL, "OrderStatus" VARCHAR(64) NOT NULL, "OrdersCount" INTEGER, "TotalSales" DECIMAL(38,18), "UniqueCustomers" INTEGER, "LastUpdated" TIMESTAMP, "SourceBatchID" VARCHAR(256) NOT NULL, PRIMARY KEY ("ProductCategoryNameEnglish", "OrderStatus")) DISTSTYLE AUTO SORTKEY ("ProductCategoryNameEnglish", "OrderStatus");
CREATE TABLE IF NOT EXISTS analytics.cross_state_analysis ("ProductCategoryNameEnglish" VARCHAR(256) NOT NULL, "IsCrossState" BOOLEAN NOT NULL, "OrdersCount" INTEGER, "TotalSales" DECIMAL(38,18), "AvgDeliveryTime" DECIMAL(38,18), "DelayRate" DECIMAL(38,18), "LastUpdated" TIMESTAMP, "SourceBatchID" VARCHAR(256) NOT NULL, PRIMARY KEY ("ProductCategoryNameEnglish", "IsCrossState")) DISTSTYLE AUTO SORTKEY ("ProductCategoryNameEnglish", "IsCrossState");
CREATE TABLE IF NOT EXISTS analytics.seller_performance ("SellerID" VARCHAR(64) NOT NULL, "SellerState" VARCHAR(8), "OrdersCount" INTEGER, "TotalSales" DECIMAL(38,18), "AvgShippingCost" DECIMAL(38,18), "AvgDeliveryTime" DECIMAL(38,18), "DelayedOrders" INTEGER, "DelayRate" DECIMAL(38,18), "LastUpdated" TIMESTAMP, "SourceBatchID" VARCHAR(256) NOT NULL, PRIMARY KEY ("SellerID")) DISTSTYLE AUTO SORTKEY ("SellerID");
CREATE TABLE IF NOT EXISTS analytics.size_analysis ("ProductCategoryNameEnglish" VARCHAR(256) NOT NULL, "SizeCategory" VARCHAR(32) NOT NULL, "OrdersCount" INTEGER, "TotalSales" DECIMAL(38,18), "AvgShippingCost" DECIMAL(38,18), "LastUpdated" TIMESTAMP, "SourceBatchID" VARCHAR(256) NOT NULL, PRIMARY KEY ("ProductCategoryNameEnglish", "SizeCategory")) DISTSTYLE AUTO SORTKEY ("ProductCategoryNameEnglish", "SizeCategory");
CREATE TABLE IF NOT EXISTS analytics.payment_methods ("PaymentType" VARCHAR(64) NOT NULL, "OrdersCount" INTEGER, "TotalSales" DECIMAL(38,18), "AvgOrderValue" DECIMAL(38,18), "UniqueCustomers" INTEGER, "LastUpdated" TIMESTAMP, "SourceBatchID" VARCHAR(256) NOT NULL, PRIMARY KEY ("PaymentType")) DISTSTYLE AUTO SORTKEY ("PaymentType");
